function buildInventoryStats(t){const e=t.stock,n=t.inOut,a=t.expired,i=t.temperature;let s="";i.forEach(t=>{s+=`\n        <div class="col-lg-3 mb-2">\n            <div class="d-flex align-items-center">\n                <span class="material-symbols-outlined text-info">ac_unit</span>\n                <div>\n                    <div class="fw-bold">${t.name} (${Number(t.temperature)} °C)</div>\n                    <div class="text-muted fs-2">\n                        Ult. actualización: ${timeAgo(t.update_temp)}\n                    </div>\n                </div>\n            </div>\n        </div>\n    `});let d=`<div class="row">\n    <div class="col-lg-3 mb-2">\n        <div class="card shadow border card-hover h-100">\n            <div class="card-body d-flex align-items-center gap-3 p-2">\n                <div class="bg-info-subtle rounded-circle p-3 d-flex justify-content-center align-items-center">\n                    <span class="material-symbols-outlined text-info" style="font-size: 2rem;">inventory</span>\n                </div>\n                <div>\n                    <div class="text-muted fw-bold h6 mb-1">STOCK</div>\n                    <div class="fw-semibold h4 mb-1">${Number(e.total).toLocaleString("en-US",{minimumFractionDigits:2})} LB</div>\n                    <div class="text-muted d-flex align-items-center">\n                        <span class="material-symbols-outlined">package_2</span>\n                        <span class="ms-2 fs-2 text-muted">${Number(e.package)} paquetes disponibles</span>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n    <div class="col-lg-3 mb-2">\n        <div class="card shadow border card-hover h-100">\n            <div class="card-body d-flex align-items-center gap-3 p-2">\n                <div class="bg-success-subtle rounded-circle p-3 d-flex justify-content-center align-items-center">\n                    <span class="material-symbols-outlined text-success" style="font-size: 2rem;">arrow_downward</span>\n                </div>\n                <div>\n                    <div class="text-muted fw-bold h6 mb-1">ENTRADAS</div>\n                    <div class="fw-semibold h4 mb-1">${Number(n.entrada.total).toLocaleString("en-US",{minimumFractionDigits:2})} LB</div>\n                    <div class="text-muted d-flex align-items-center">\n                        <span class="material-symbols-outlined">package_2</span>\n                        <span class="ms-2 fs-2 text-muted">${Number(n.entrada.package)} paquetes disponibles</span>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n    <div class="col-lg-3 mb-2">\n        <div class="card shadow border card-hover h-100">\n            <div class="card-body d-flex align-items-center gap-3 p-2">\n                <div class="bg-primary-subtle rounded-circle p-3 d-flex justify-content-center align-items-center">\n                    <span class="material-symbols-outlined text-primary" style="font-size: 2rem;">arrow_left_alt</span>\n                </div>\n                <div>\n                    <div class="text-muted fw-bold h6 mb-1">SALIDAS</div>\n                    <div class="fw-semibold h4 mb-1">${Number(n.salida.total).toLocaleString("en-US",{minimumFractionDigits:2})} LB</div>\n                    <div class="text-muted d-flex align-items-center">\n                        <span class="material-symbols-outlined">package_2</span>\n                        <span class="ms-2 fs-2 text-muted">${Number(n.salida.package)} paquetes vendidos</span>\n                    </div>\n                </div>\n            </div>\n        </div>\n    </div>\n    <div class="col-lg-3 mb-2">\n        <div class="card shadow border card-hover h-100">\n            <div class="card-body d-flex align-items-center gap-3 p-2">\n                <div class="bg-danger-subtle rounded-circle p-3 d-flex justify-content-center align-items-center">\n                    <span class="material-symbols-outlined text-danger" style="font-size: 2rem;">warning</span>\n                </div>\n                <div>\n                    <div class="text-muted fw-bold h6 mb-1">POR VENCER</div>\n                    <div class="fw-semibold h4 mb-1">${Number(a.total)}</div>\n                    <span class="fs-2 text-muted">Menos de 30 días</span>\n                </div>\n            </div>\n        </div>\n    </div>\n    ${s}\n</div>\n<div class="row">\n    <div class="col-lg-8 col-12">\n        <div class="card w-100 mb-2">\n            <div class="card-body p-0">\n                <div id="chart1" class="mt-3"></div>\n            </div>\n        </div>\n    </div>\n    <div class="col-lg-4 col-12">\n        <div class="card w-100 mb-2">\n            <div class="card-body p-0">\n                <div id="chart4" class="mt-3"></div>\n            </div>\n        </div>\n    </div>\n    <div class="col-lg-4 col-12">\n        <div class="card w-100 mb-2">\n            <div class="card-body p-0">\n                <div id="chart2" class="mt-3"></div>\n            </div>\n        </div>\n    </div>\n    <div class="col-lg-8 col-12">\n        <div class="card w-100 mb-2">\n            <div class="card-body p-0">\n                <div id="chart3" class="mt-3"></div>\n            </div>\n        </div>\n    </div>\n    <div class="col-lg-12 col-12">\n        <div class="card w-100 mb-2" id="dataExpired">\n        </div>\n    </div>\n</div>`;$("#stats").empty().html(d)}function buildInventoryGraph(t){const e=t.map(t=>{const[e,n,a]=t.fecha.split("-");return`${a}/${n}`}),n={series:[{name:"Compras",data:t.map(t=>Number(t.entradas))},{name:"Ventas",data:t.map(t=>Number(t.salidas))},{name:"Producción",data:t.map(t=>Number(t.produccion))},{name:"Merma",data:t.map(t=>Number(t.merma))}],chart:{type:"line",height:350,toolbar:{show:!1}},title:{text:"Flujo del inventario por día",align:"left"},xaxis:{categories:e},colors:["#16deb9","#5d87ff","#6851d7","#f70167"],stroke:{curve:"smooth",width:3},markers:{size:0},yaxis:{labels:{formatter:function(t){return t?t.toLocaleString()+" LB":0}}},tooltip:{shared:!0,intersect:!1}};new ApexCharts(document.querySelector("#chart1"),n).render()}function buildInventoryGraphLocation(t){const e=t.map(t=>t.name),n={series:[{name:"Ubicaciones",data:t.map(t=>Number(t.total))}],chart:{type:"bar",height:350,toolbar:{show:!1}},title:{text:"Stock por ubicación",align:"left"},plotOptions:{bar:{horizontal:!0,borderRadius:4,borderRadiusApplication:"end"}},colors:["#1a2e56"],xaxis:{categories:e},tooltip:{y:{formatter:function(t){return Number(t).toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2})+" LB"},title:{formatter:()=>""}}}};new ApexCharts(document.querySelector("#chart2"),n).render()}function buildInventoryGraphProducts(t){const e=t.map(t=>{const e=t.name.split(" ");if(t.name.length<=20)return t.name;const n=Math.ceil(e.length/2);return[e.slice(0,n).join(" "),e.slice(n).join(" ")]}),n={series:[{name:"Stock",data:t.map(t=>Number((Number(t.total)/2200).toFixed(2)))}],chart:{type:"bar",height:500,toolbar:{show:!1}},title:{text:"Stock por producto",align:"left"},colors:["#1565C0"],plotOptions:{bar:{borderRadius:4,borderRadiusApplication:"end",horizontal:!0}},xaxis:{categories:e,labels:{formatter:function(t){return Number(t)+"T"}}},tooltip:{y:{formatter:function(t){const e=Number(t);return`\n                        ${(2200*e).toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2})} Libras\n                        <br>\n                        ${e.toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2})} Toneladas\n                    `},title:{formatter:()=>""}}}};new ApexCharts(document.querySelector("#chart3"),n).render()}function buildInventoryGraphTotal(t){const e={series:[Number(t.entradas),Number(t.salidas),Number(t.produccion),Number(t.merma)],chart:{type:"pie",height:350},labels:["Compras","Ventas","Producción","Merma"],colors:["#16deb9","#5d87ff","#6851d7","#f70167"],title:{text:"Resumen de inventario",align:"left"},plotOptions:{pie:{dataLabels:{external:{show:!0}}}},tooltip:{y:{formatter:function(t){return Number(t).toLocaleString("en-US",{minimumFractionDigits:2,maximumFractionDigits:2})+" LB"}}},legend:{position:"bottom"}};new ApexCharts(document.querySelector("#chart4"),e).render()}function buildInventoryDataExpired(t){let e="";t.forEach(t=>{e+=`<tr>\n        <td class="fw-semibold text-primary">${t.batch_code}</td>\n        <td>${t.producto}</td>\n        <td>${t.subproducto}</td>\n        <td>${t.expiration_date}</td>\n        <td>${t.dias} días</td>\n        </tr>`});let n=`\n    <div class="card-header">\n        <div class="mb-2 fw-semibold h5 text-dark">Proximos a expirar</div>\n    </div>\n    <div class="card-body p-2 table-responsive">\n        <table class="table table-sm table-borderless">\n            <thead>\n                <tr>\n                <th>Lote</th>\n                <th>Producto</th>\n                <th>Subproducto</th>\n                <th>Expiración</th>\n                <th>Expira en</th>\n                </tr>\n            </thead>\n            <tbody>\n            ${e}\n            </tbody>\n        </table>\n    </div>`;$("#dataExpired").empty().html(n)}function timeAgo(t){const e=new Date,n=new Date(t.replace(" ","T")),a=Math.floor((e-n)/1e3);if(a<60)return`hace ${a} sg`;const i=Math.floor(a/60);if(i<60)return`hace ${i} min`;const s=Math.floor(i/60);if(s<24)return`hace ${s} h`;const d=Math.floor(s/24);if(d<30)return`hace ${d} ${1===d?"día":"días"}`;const r=Math.floor(d/30);if(r<12)return`hace ${r} ${1===r?"mes":"meses"}`;const o=Math.floor(d/365);return`hace ${o} ${1===o?"año":"años"}`}
